 .separater {
  font-size: 16px;
  width: 1.5em;
  margin: auto;
  display: grid;
  gap: 1.0em;
}

 .separater span {
  display: block;
  color: #ccc;
  aspect-ratio: 1/1;
  border-radius: 50%;
  margin: auto;
  width: 100%;
  animation: gradation 1s ease-in-out infinite;
}

 .separater span:nth-of-type(1) {
  animation-delay: 0;
}

 .separater span:nth-of-type(2) {
  animation-delay: 0.15s;
}

 .separater span:nth-of-type(3) {
  animation-delay: 0.25s;

}

@keyframes gradation {
  0% {
    background: transparent;
  }

  100% {
    background: currentColor;
  }
}

.partition__area {
  position: relative;
  height: 1em !important;
  z-index: 0;
}

.partition__area .partition {
  width: calc(100% + 40px);
  max-width: calc(100% + 40px);
  height: 1em !important;
  position: absolute;
  top: 0;
  left: -20px;
  background: #f4f4f4;
}

 .separater-side {
  font-size: 16px;
  margin-inline: auto;
  width: calc(1.5em * 3);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.0em;
  box-sizing: border-box;
}

 .separater-side span {
  width: 1.5em;
  display: block;
  background-color: #d77f9b;
  aspect-ratio: 1/1;
  border-radius: 50%;
  margin: auto;
  box-sizing: border-box;
}

 .separater-side span:nth-of-type(1) {
  background-color: #d77f9b;
}

 .separater-side span:nth-of-type(2) {
  background-color: #d99db0;
}

 .separater-side span:nth-of-type(3) {
  background-color: #f4abc2;
}

.separater {
	font-size: 16px;
	width: 1.5em;
	margin: auto;
	display: grid;
	gap: 1.0em;
}
.separater span {
	display: block;
	background-color: #000;
	aspect-ratio: 1/1;
	border-radius: 50%;
	margin: auto;

}
.separater span:nth-of-type(1) {
	width: 100%;
	background-color: #d77f9b;
}
.separater span:nth-of-type(2) {
	width: calc(100% / 2);
	background-color:#d99db0;
}
.separater span:nth-of-type(3) {
	width: calc(100% / 3);
	background-color: #f4abc2;
}

.ranking {
  border-bottom: solid 5px;
  position: relative;
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 0.5em;
}

.ranking::before {
  content: attr(data-rank) "位";
  width: 4.5em;
  aspect-ratio: 17/11;
  color: #FFF;
  font-weight: 600;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  background: url(/uploads/f0f99fb830593ce7c2535802e165dcfbabe40f1659f165b14a98695fd8f1df3e.png) no-repeat 0 0/contain;
  padding-top: 0.25em;
}

.ranking-title {
  font-weight: 600;
  line-height: 1;
  flex: 1 0 auto;
  margin-top: 0.5em;
  position: relative;
}

.ranking[data-rank="1"] {
  border-color: #aca06b;
}

.ranking[data-rank="1"]::before {
  background-image: url(/uploads/b13ce5383b5950ad1131289f77011b9d8413c2779e8d1079df4740dd1af9c53b.png);
}

.ranking[data-rank="2"] {
  border-color: #9f9f9f;
}

.ranking[data-rank="2"]::before {
  background-image: url(/uploads/faaeeaebf33e57952fe3c30890619bd4073044a1c6a9435f539167eac667be47.png);
}

.ranking[data-rank="3"] {
  border-color: #a26a44;
}

.ranking[data-rank="3"]::before {
  background-image: url(/uploads/610bc6199f9e273e53285745b26bd7f82ee08efeaa845975df9678466b1c0e4c.png);
}

.ranking.center {
  justify-content: center;
}

.ranking.center .ranking-title {
  flex: 0 1 auto;
}

@media (max-width: 480px) {
  .ranking {
    font-size: 3.8vw;
  }
}

.ranking-header {
  font-size: 16px;
  border-top: solid 5px;
  position: relative;
  margin-top: 2.5em;
}

.ranking-header::before,
.ranking-header::after {
  content: "";
  display: block;
  position: absolute;
  width: 4.5em;
  aspect-ratio: 17/11;
  top: -2.5em;
  left: 0.5em;
}

.ranking-header::before {
  content: attr(data-ranking) "";
  z-index: 10;
  text-align: center;
  color: #FFF;
  font-size: 1em;
  font-weight: 600;
  line-height: 3.5;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ranking-header::after {
  content: "";
  background: url(/uploads/f0f99fb830593ce7c2535802e165dcfbabe40f1659f165b14a98695fd8f1df3e.png) no-repeat 0 0/contain;
  z-index: 1;
}

.ranking-header[data-ranking="1"] {
